    private static final Pattern RESIDUAL_PATTERN = Pattern.compile("^(0|[1-9]\\d{0,2})(\\.\\d{1,6})?$");
    private static final String CMD_REGISTER = "REGISTER_SEQUENCE";
    private static final String CMD_CLEANING_SUBMIT = "SUBMIT_CLEANING";
    private static final String CMD_CLEANING_CONFIRM = "CONFIRM_CLEANING";

    private final LineRepository lineRepo;
    private final BatchRepository batchRepo;
    private final IdempotencyExecutor idempotency;
    private final ObjectMapper objectMapper;

    register(String lineId, String actorId, RegisterSequenceRequest req):
        String operator = requireActor(actorId);
        int expected = req.expectedVersion().intValueExact? Long → check <= Integer.MAX_VALUE; use long compare with line.nextSeq.
        Map identity = orderedIdentity("REGISTER_SEQUENCE", operator, "line:" + lineId, req.expectedVersion(), Map.of("batchKey", req.batchKey()));
        return idempotency.execute(CMD_REGISTER, req.requestId(), identity, () -> {
            LineRow line = lockLine(lineId);
            if (req.expectedVersion() != line.nextSeq()) throw conflict("顺序号不连续...");
            BatchRow batch = batchRepo.findBatch(req.batchKey()).orElseThrow(notFound);
            lineRepo.findSequenceByBatch(req.batchKey()).ifPresent(s -> throw conflict("批次已登记..."));
            LineSequenceRow prev = last of findSequences(lineId);
            String prevKey = prev == null ? null : prev.batchKey();
            if (prevKey != null) {
                BatchRow prevBatch = batchRepo.findBatch(prevKey).orElseThrow(...); // must exist
                if (!prevBatch.productCode().equals(batch.productCode()) && !hasValidCleaning(lineId, prevKey, req.batchKey())) {
                    throw unprocessable("前后批产品不同且不存在有效清洗记录...");
                }
            }
            insert sequence with seq = line.nextSeq(); updateNextSeq(nextSeq+1);
            return new StoredResponse(201, toJson(new LineSequenceResponse(...)));
        });
