        // 第一次清洗残留 0.100001 毫克（未舍入判断超过 0.1）：确认被 422 阻断，不产生有效清洗
        submitCleaning(line, "CL-1", a, b, "0.100001", 0, "RID-" + unique(), "cleaner-1", 201);
        confirm("CL-1", "qa-1", "QUALITY", 0, "RID-" + unique(), 422);
